mapper.select:
SELECT COUNT(*)
FROM event_seats
WHERE event_id = #{eventId}

SELECT venue_section.id AS section_id, venue_section.name AS section_name, venue_section.display_order AS section_display_order, seat.row_label, event_seat.id AS event_seat_id, seat.seat_label, seat.seat_number, event_seat.price, event_seat.permanent_status, seat.accessible FROM events e JOIN event_seats event_seat ON event_seat.event_id = e.id JOIN seats seat ON seat.id = event_seat.seat_id JOIN venue_sections venue_section ON venue_section.id = seat.section_id WHERE e.id = #{eventId} AND e.status = 'PUBLISHED'
AND seat.section_id = #{sectionId}
ORDER BY venue_section.display_order ASC, venue_section.name ASC, venue_section.id ASC, seat.row_label ASC, seat.seat_number ASC, seat.seat_label ASC, event_seat.id ASC
